package space.glidetv.bridge;
import android.net.LocalServerSocket;import android.net.LocalSocket;import org.json.*;import java.io.*;import java.util.*;import java.util.regex.*;
/** Loopback-only shell helper. A random launcher-owned token authenticates fixed, allowlisted operations. */
public final class MemoryBridge {
 static final File SHARE_ROOT=new File("/sdcard");
 static String run(String... args)throws Exception{Process p=new ProcessBuilder(args).redirectErrorStream(true).start();StringBuilder out=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()))){String s;while((s=r.readLine())!=null){out.append(s).append('\n');if(out.length()>1500000)throw new IOException("Output limit");}}int code=p.waitFor();if(code!=0)throw new IOException(out.toString());return out.toString();}
 static int owner()throws Exception{Matcher m=Pattern.compile("uid:(\\d+)").matcher(run("cmd","package","list","packages","-U","space.glidetv.launcher"));if(!m.find())throw new IOException("Launcher not installed");return Integer.parseInt(m.group(1));}
 static JSONObject memory()throws Exception{JSONObject data=new JSONObject();try(BufferedReader r=new BufferedReader(new FileReader("/proc/meminfo"))){String line;while((line=r.readLine())!=null){String[] parts=line.trim().split("\\s+");if(parts.length>1)data.put(parts[0].replace(":",""),Long.parseLong(parts[1]));}}
 String dump=run("dumpsys","meminfo");JSONArray top=new JSONArray();boolean section=false;Pattern linePattern=Pattern.compile("\\s*([\\d,]+)K:\\s+(.+?)\\s+\\(pid\\s+(\\d+).*");for(String line:dump.split("\n")){if(line.trim().equals("Total PSS by process:")){section=true;continue;}if(section&&line.startsWith("Total PSS by "))break;if(section){Matcher m=linePattern.matcher(line);if(m.matches()&&top.length()<12){JSONObject entry=new JSONObject();entry.put("name",m.group(2));entry.put("kb",Long.parseLong(m.group(1).replace(",","")));top.put(entry);}}}data.put("processes",top);data.put("ok",true);return data;}
 static void stop(String pkg)throws Exception{if(!pkg.matches("[a-zA-Z0-9_]+(?:\\.[a-zA-Z0-9_]+)+")||pkg.equals("space.glidetv.launcher")||pkg.startsWith("com.android.")||pkg.startsWith("com.tcl.")||pkg.startsWith("com.mediatek.")||pkg.equals("com.google.android.gms")||pkg.equals("com.google.android.gsf")||pkg.equals("com.google.android.katniss")||pkg.equals("com.google.android.tv.remote.service"))throw new IOException("Protected process");String tv=run("cmd","package","query-activities","--brief","-a","android.intent.action.MAIN","-c","android.intent.category.LEANBACK_LAUNCHER","-p",pkg),regular=run("cmd","package","query-activities","--brief","-a","android.intent.action.MAIN","-c","android.intent.category.LAUNCHER","-p",pkg);if(!tv.contains(pkg+"/")&&!regular.contains(pkg+"/"))throw new IOException("No app launcher");run("am","force-stop","--user","0",pkg);}
 static void key(String name)throws Exception{String code;switch(name){case "home":code="3";break;case "back":code="4";break;case "up":code="19";break;case "down":code="20";break;case "left":code="21";break;case "right":code="22";break;case "ok":code="23";break;default:throw new IOException("Unsupported key");}run("/system/bin/input","keyevent",code);}
 static File safeFile(String relative)throws Exception{if(relative==null||relative.length()>1024||relative.startsWith("/")||relative.indexOf('\\')>=0||relative.indexOf('\0')>=0)throw new IOException("Invalid storage path");for(String part:relative.split("/"))if(part.equals(".."))throw new IOException("Invalid storage path");File root=SHARE_ROOT.getCanonicalFile(),file=new File(root,relative).getCanonicalFile();String path=file.getPath();if(!path.equals(root.getPath())&&!path.startsWith(root.getPath()+File.separator))throw new IOException("Storage path is outside shared storage");if(path.equals(root.getPath()+File.separator+"Android")||path.startsWith(root.getPath()+File.separator+"Android"+File.separator))throw new IOException("Android private folders are not exposed");return file;}
 static JSONObject list(String relative)throws Exception{File dir=safeFile(relative);if(!dir.isDirectory())throw new IOException("Folder not found");File[] files=dir.listFiles();if(files==null)throw new IOException("Folder cannot be read");Arrays.sort(files,(a,b)->{if(a.isDirectory()!=b.isDirectory())return a.isDirectory()?-1:1;return a.getName().compareToIgnoreCase(b.getName());});JSONArray entries=new JSONArray();for(File f:files){if(entries.length()>=500)break;String name=f.getName();if(name.equals("Android")&&relative.isEmpty())continue;File safe;try{safe=safeFile(relative.isEmpty()?name:relative+"/"+name);}catch(Exception ignored){continue;}JSONObject item=new JSONObject();item.put("name",name);item.put("path",relative.isEmpty()?name:relative+"/"+name);item.put("directory",safe.isDirectory());item.put("size",safe.isFile()?safe.length():0);item.put("modified",safe.lastModified());entries.put(item);}JSONObject out=new JSONObject();out.put("ok",true);out.put("path",relative);out.put("parent",relative.contains("/")?relative.substring(0,relative.lastIndexOf('/')):"");out.put("entries",entries);return out;}
 static JSONObject fileInfo(String relative)throws Exception{File f=safeFile(relative);if(!f.isFile())throw new IOException("File not found");JSONObject r=new JSONObject();r.put("ok",true);r.put("name",f.getName());r.put("size",f.length());r.put("modified",f.lastModified());return r;}
 static JSONObject upload(DataInputStream input)throws Exception{String name=input.readUTF();if(name.length()>120||name.isEmpty()||name.equals(".")||name.equals("..")||name.contains("/")||name.contains("\\")||name.indexOf('\0')>=0)throw new IOException("Invalid file name");long size=input.readLong();if(size<0||size>2L*1024*1024*1024)throw new IOException("File exceeds 2 GB limit");File folder=safeFile("Download/Glide Remote");if(!folder.exists()&&!folder.mkdirs())throw new IOException("Could not create Download/Glide Remote");File target=safeFile("Download/Glide Remote/"+name);if(target.exists())throw new IOException("A file with that name already exists");try(FileOutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[65536];long copied=0;while(copied<size){int n=input.read(buffer,0,(int)Math.min(buffer.length,size-copied));if(n<0)throw new EOFException("Upload ended early");out.write(buffer,0,n);copied+=n;}}JSONObject r=new JSONObject();r.put("ok",true);r.put("name",name);r.put("path","Download/Glide Remote/"+name);r.put("size",target.length());return r;}
 public static void main(String[] args)throws Exception{try(java.net.ServerSocket server=new java.net.ServerSocket(43817,4,java.net.InetAddress.getByAddress(new byte[]{127,0,0,1}))){while(true){try(java.net.Socket socket=server.accept()){socket.setSoTimeout(120000);java.io.DataInputStream input=new java.io.DataInputStream(socket.getInputStream());String supplied=input.readUTF(),expected;try(BufferedReader reader=new BufferedReader(new FileReader("/sdcard/Android/data/space.glidetv.launcher/files/ram-helper-token"))){expected=reader.readLine();}if(expected==null||expected.length()!=64||!java.security.MessageDigest.isEqual(expected.getBytes("UTF-8"),supplied.getBytes("UTF-8")))continue;String op=input.readUTF();JSONObject result;
 try{if("snapshot".equals(op))result=memory();else if("clear".equals(op)){run("am","kill-all");Thread.sleep(800);result=memory();result.put("cleared",true);}else if(op.startsWith("stop:")){stop(op.substring(5));Thread.sleep(400);result=memory();result.put("stopped",true);}else if(op.startsWith("key:")){key(op.substring(4));result=new JSONObject().put("ok",true);}else if(op.startsWith("list:"))result=list(op.substring(5));else if(op.startsWith("stat:"))result=fileInfo(op.substring(5));else if(op.startsWith("read:")){String relative=op.substring(5);JSONObject info=fileInfo(relative);File source=safeFile(relative);java.io.DataOutputStream output=new java.io.DataOutputStream(socket.getOutputStream());output.writeUTF(info.toString());output.writeLong(source.length());try(FileInputStream file=new FileInputStream(source)){byte[] buffer=new byte[65536];int n;while((n=file.read(buffer))!=-1)output.write(buffer,0,n);}output.flush();continue;}else if("upload".equals(op))result=upload(input);else throw new IOException("Unsupported operation");}catch(Exception e){e.printStackTrace();result=new JSONObject();result.put("ok",false);result.put("error",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}
 java.io.DataOutputStream output=new java.io.DataOutputStream(socket.getOutputStream());output.writeUTF(result.toString());output.flush();}catch(Exception e){e.printStackTrace();}}}}
}
